#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk #:package MQTTnet@4.3.2.930 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable using System; using System.Text; using System.Threading.Tasks; using MQTTnet; using MQTTnet.Client;  namespace MQTTNetDemo {     /// <summary>     /// MQTT演示程序 - 客户端版     /// </summary>     public class Program     {         public static async Task Main(string[] args)         {             Console.WriteLine("MQTTnet Client Demo Starting...");              try             {                 // 创建MQTT工厂                 var factory = new MqttFactory();                  // 创建MQTT客户端                 var client = factory.CreateMqttClient();                  // 配置客户端选项                 var clientOptions = new MqttClientOptions                 {                     ChannelOptions = new MqttClientTcpOptions                     {                         Server = "127.0.0.1",                         Port = 1883                     },                     ClientId = "DemoClient1",                     CleanSession = true                 };                  // 连接到服务器                 await client.ConnectAsync(clientOptions);                 Console.WriteLine("Connected to MQTT server");                  // 订阅主题                 await client.SubscribeAsync("demo/topic");                 Console.WriteLine("Subscribed to topic 'demo/topic'");                  // 设置消息接收回调                 client.ApplicationMessageReceivedAsync += e =>                 {                     var topic = e.ApplicationMessage.Topic;                     var payload = Encoding.UTF8.GetString(e.ApplicationMessage.Payload);                     Console.WriteLine($"Received message: Topic={topic}, Payload={payload}");                     return Task.CompletedTask;                 };                  // 发布测试消息                 var message = new MqttApplicationMessage                 {                     Topic = "demo/topic",                     Payload = Encoding.UTF8.GetBytes("Hello from MQTT client!")                 };                  await client.PublishAsync(message);                 Console.WriteLine("Published message: Hello from MQTT client!");                  // 等待用户输入退出                 Console.WriteLine("\nMQTT Client is running. Press any key to exit...");                 Console.ReadKey();                  // 断开连接                 await client.DisconnectAsync();                 Console.WriteLine("Disconnected from MQTT server");             }             catch (Exception ex)             {                 Console.WriteLine($"Error: {ex.Message}");                 Console.WriteLine($"Stack trace: {ex.StackTrace}");                 Console.ReadKey();             }         }     } }
